.wp-block-jetpack-subscriptions-form input[type="email"] {
 background-color: #FFEB3B !important; /* A vibrant yellow */
 color: #000000 !important; /* Solid black text */
}

/* Ensure the placeholder text (the example email) is also dark */
.wp-block-jetpack-subscriptions-form input::placeholder {
 color: #333333 !important;
 opacity: 0.7 !important;
}

/* Specific fix for Webkit browsers (Chrome/Safari) */
.wp-block-jetpack-subscriptions-form input::-webkit-input-placeholder {
 color: #333333 !important;
}"},"core/site-title":{"typography":{"fontFamily":"var(--wp--preset--font-family--noto-sans-mono)","fontSize":"var(--wp--preset--font-size--small)","fontWeight":"400","textTransform":"uppercase"}},"core/navigation":{"typography":{"fontFamily":"var(--wp--preset--font-family--noto-sans-mono)","fontSize":"var(--wp--preset--font-size--small)","fontWeight":"400","lineHeight":"1.4","textTransform":"uppercase"}},"core/separator":{"color":{"text":"var(--wp--preset--color--theme-3)"}},"core/column":{"variations":{"section-1":{"color":{"background":"var(--wp--preset--color--theme-4)","text":"var(--wp--preset--color--theme-1)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-3) 85%, #000)","text":"var(--wp--preset--color--theme-1)"}}}}},"section-2":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-1)","text":"var(--wp--preset--color--theme-3)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-1) 85%, #000)","text":"var(--wp--preset--color--theme-3)"}}}}},"section-3":{"color":{"background":"var(--wp--preset--color--theme-1)","text":"var(--wp--preset--color--theme-5)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-3) 85%, #000)","text":"var(--wp--preset--color--theme-1)"}}}}}}},"core/columns":{"variations":{"section-1":{"color":{"background":"var(--wp--preset--color--theme-4)","text":"var(--wp--preset--color--theme-1)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--pr