(--wp--preset--color--theme-1)"}}}}}}},"core/cover":{"variations":{"section-1":{"color":{"background":"var(--wp--preset--color--theme-4)","text":"var(--wp--preset--color--theme-1)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-3) 85%, #000)","text":"var(--wp--preset--color--theme-1)"}}}}},"section-2":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-1)","text":"var(--wp--preset--color--theme-3)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-1) 85%, #000)","text":"var(--wp--preset--color--theme-3)"}}}}},"section-3":{"color":{"background":"var(--wp--preset--color--theme-1)","text":"var(--wp--preset--color--theme-5)"},"elements":{"button":{"color":{"background":"var(--wp--preset--color--theme-3)","text":"var(--wp--preset--color--theme-1)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--theme-3) 85%, #000)","text":"var(--wp--preset--color--theme-1)"}}}}}}}},"typography":{"fontFamily":"var(--wp--preset--font-family--readable-sans)","fontSize":"16px","fontStyle":"normal","textTransform":"none","fontWeight":"400","lineHeight":"1.7"},"color":{"background":"hsl(45, 60%, 94%)","text":"hsl(210, 24%, 16%)"},"css":".wpcom-ai-mission-wrapper {
	background-color: #fdfaf5;
}

.wpcom-ai-article-heading-contrast {
	color: var(--wp--preset--color--theme-5) !important;
}

@media (max-width: 600px) {
	.wpcom-ai-mobile-heading-contrast .wp-block-group.has-theme-2-background-color h1,
														.wpcom-ai-mobile-heading-contrast .wp-block-group.has-theme-2-background-color h2,
														.wpcom-ai-mobile-heading-contrast .wp-block-group.has-theme-2-background-color h3,
														.wpcom-ai-mobile-heading-contrast .wp-block-group.has-theme-2-background-color h4,
														.wpcom-ai-mobile-heading-contrast .wp-block-group.has-theme-2-background-color h5,
														.wpcom-ai-mobile-heading-contrast .wp-block-group.has-theme-2-background-color h6 {
		color: #304865;
		text-wrap: balance;
	}

	.wpcom-ai-mobile-heading-contrast .wp-block-heading {
		color: #304865 !important;
	}
}

.wpcom-ai-page-title {
	letter-spacing: -.02em;
	line-height: 1.1;
}

.wpcom-ai-fit-text-button .wp-block-button__link {
	width: max-content;
	max-width: 100%;
}

.wpcom-ai-two-line-button .wp-block-button__link .wpcom-ai-button-title,
.wpcom-ai-two-line-button .wp-block-button__link .wpcom-ai-button-subtitle {
	display: block;
}

.wpcom-ai-two-line-button .wp-block-button__link .wpcom-ai-button-title {
	font-size: 1.15em;
	font-weight: 600;
	line-height: 1.2;
}

.wpcom-ai-two-line-button .wp-block-button__link .wpcom-ai-button-subtitle {
	font-size: .82em;
	line-height: 1.35;
}

.wpcom-ai-ten-marks-title {
	white-space: nowrap;
}

.wpcom-ai-kicker {
	color: var(--wp--preset--color--theme-3);
	letter-spacing: .01em;
}

.wpcom-ai-standfirst {
	color: var(--wp--preset--color--theme-4);
	line-height: 1.5;
}

.wpcom-ai-rule {
	margin-top: .5em;
	margin-bottom: .5em;
	width: 60px;
	max-width: 60px;
}

.wpcom-ai-lede p,
.wpcom-ai-lede {
	font-size: 1.15em;
	line-height: 1.75;
}

.wpcom-ai-pull-emphasis {
	font-style: italic;
	color: var(--wp--preset--color--theme-4);
	border-left: 3px solid var(--wp--preset--color--theme-3);
	padding-left: 1.25em;
	margin-top: .25em;
	margin-bottom: .25em;
}

.wpcom-ai-section-heading {
	letter-spacing: -.01em;
	line-height: 1.2;
}

.wpcom-ai-editorial-subheading {
	text-decoration-line: underline;
	text-decoration-color: var(--wp--preset--color--theme-3);
	text-underline-offset: .22em;
}

@media (max-width: 600px) {
	.wpcom-ai-editorial-subheading {
		text-wrap: balance;
		text-underline-offset: .18em;
	}
}

.wpcom-ai-commitment-section {
	margin-top: var(--wp--preset--spacing--60);
}

.wpcom-ai-progression {
	letter-spacing: .04em;
	color: var(--wp--preset--color--theme-3);
}

.wpcom-ai-rule-light {
	width: 80px;
	max-width: 80px;
	margin-left: auto;
	margin-right: auto;
}

.wpcom-ai-subsection-rule {
	width: 72px;
	max-width: 72px;
	margin-left: auto;
	margin-right: auto;
	opacity: .65;
}

.wp-block-post-content p {
	line-height: 1.8;
}

.wpcom-ai-pub-item {
	transition: opacity .2s ease;
}

.wpcom-ai-mission-section {
	box-shadow: inset 0 1px 0 rgba(255,255,255,0.18), inset 0 -1px 0 rgba(0,0,0,0.08);
}

.wpcom-ai-mission-section > .wp-block-separator {
	margin-top: 0;
	margin-bottom: var(--wp--preset--spacing--30);
}

.wpcom-ai-mission-section > p {
	max-width: 68ch;
	margin-left: auto;
	margin-right: auto;
	line-height: 1.75;
}

.wpcom-ai-mission-section > p:first-of-type {
	margin-top: 0;
}

.wpcom-ai-mission-section > p:not(:first-of-type) {
	text-wrap: pretty;
}

.wpcom-ai-mission-section > p.has-large-font-size {
	max-width: 34ch;
	margin-top: var(--wp--preset--spacing--30);
	margin-bottom: var(--wp--preset--spacing--20);
	letter-spacing: -.01em;
}

.wpcom-ai-mission-section > p strong {
	font-weight: 600;
}

.wpcom-ai-pub-item:hover {
	opacity: .85;
}

.wpcom-ai-founder-title {
	max-width: 52ch;
	letter-spacing: .01em;
	text-wrap: balance;
}

.wpcom-ai-founder-credential {
	max-width: 42ch;
	padding-left: 1rem;
	border-left: 2px solid var(--wp--preset--color--theme-3);
	text-wrap: balance;
}

.wpcom-ai-founder-credential + .wpcom-ai-founder-credential {
	margin-top: var(--wp--preset--spacing--20);
}

@media (max-width: 600px) {
	.wpcom-ai-founder-subtitle,
							.wpcom-ai-founder-credential {
		max-width: none;
	}
}

.wpcom-ai-pub-item.wpcom-ai-pub-item img {
	display: block;
	width: 100%;
	height: auto;
	border-radius: 2px;
	box-shadow: 0 4px 20px rgba(0,0,0,0.45);
	object-fit: cover;
}

.wpcom-ai-hero-divider {
	width: 80px;
	max-width: 80px;
	margin-left: auto;
	margin-right: auto;
}

.wpcom-ai-mark-item {
	max-width: 48rem;
	margin: 0 auto;
	padding: 1.15rem 1.25rem 1.2rem;
	border-bottom: 1px solid color-mix(in srgb, var(--wp--preset--color--theme-3) 28%, transparent);
	font-family: var(--wp--preset--font-family--elegant-serif);
	font-size: clamp(1.05rem, 1.8vw, 1.25rem);
	line-height: 1.65;
	letter-spacing: .005em;
	text-wrap: pretty;
}

.wpcom-ai-mark-item:first-of-type {
	padding-top: .35rem;
}

.wpcom-ai-mark-item:last-of-type {
	border-bottom: 0;
	padding-bottom: .35rem;
}

@media (max-width: 600px) {
	.wpcom-ai-mark-item {
		padding: 1rem .25rem 1.05rem;
		font-size: 1.05rem;
		line-height: 1.6;
	}
}"},"settings":{"color":{"palette":{"theme":[{"color":"#000000","name":"Color 1","slug":"theme-1"},{"color":"#D9C29A","name":"Color 2","slug":"theme-2"},{"color":"#D2A54A","name":"Color 3","slug":"theme-3"},{"color":"#586E8A","name":"Color 4","slug":"theme-4"},{"color":"#304865","name":"Color 5","slug":"theme-5"}]}},"typography":{"fontSizes":{"theme":[{"name":"Small","size":"14px","slug":"small","fluid":{"min":"13px","max":"14px"}},{"name":"Medium","size":"18px","slug":"medium","fluid":{"min":"16px","max":"18px"}},{"name":"Large","size":"28px","slug":"large","fluid":{"min":"24px","max":"28px"}},{"name":"Extra Large","size":"62px","slug":"x-large","fluid":{"min":"36px","max":"62px"}},{"name":"2X Large","size":"74px","slug":"xx-large","fluid":{"min":"40px","max":"74px"}},{"name":"3X Large","size":"168px","slug":"xxx-large","fluid":{"min":"40px","max":"168px"}}]},"fontFamilies":{"theme":[{"fontFace":[{"fontFamily":"Instrument Serif","fontStyle":"normal","fontWeight":"400 700","src":["file:./assets/fonts/instrument-serif/InstrumentSerif-Regular.woff2"]},{"fontFamily":"Instrument Serif","fontStyle":"italic","fontWeight":"400 700","src":["file:./assets/fonts/instrument-serif/InstrumentSerif-Italic.woff2"]}],"fontFamily":""Instrument Serif", serif","name":"Instrument Serif","slug":"instrument-serif"},{"fontFace":[{"fontFamily":"Noto Sans Mono","fontStretch":"normal","fontStyle":"normal","fontWeight":"100 800","src":["file:./assets/fonts/noto-sans-mono/NotoSansMono-VariableFont_wdth_wght.woff2"]}],"fontFamily":""Noto Sans Mono", monospace","name":"Noto Sans Mono","slug":"noto-sans-mono"}],"custom":[{"fontFamily":"'Playfair Display', 'Times New Roman', serif","name":"Elegant Serif","slug":"elegant-serif"},{"fontFamily":"'Source Sans Pro', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif","name":"Readable Sans","slug":"readable-sans"}]}}},"version":3,"isGlobalStylesUserThemeJSON":true}
